      const adapter = createExecutorAdapter({
        hermesExecutorDist: "/hermes/dist",
        hermesModel: "deepseek-v4-flash",
        hermesProvider: "deepseek",
        deepseekApiKey: "sk-test",
      });
      expect(adapter).toBeInstanceOf(SubProcessAdapter);
    });
  });

  it("throws for unknown EXECUTOR_PROFILE", () => {
    withEnv({ EXECUTOR_PROFILE: "unknown-profile" }, () => {
      expect(() => createExecutorAdapter({})).toThrow(
        "Unknown EXECUTOR_PROFILE: unknown-profile",
      );
    });
  });

  it("adapter supervisionSize starts at 0 (no submissions yet)", () => {
    withEnv({ EXECUTOR_PROFILE: undefined, EXECUTOR_TYPE: undefined }, () => {
      const adapter = createExecutorAdapter({ claudeExecutorDist: "/claude/dist" });
      expect((adapter as SubProcessAdapter).supervisionSize()).toBe(0);
    });
  });

  it("merges extraEnv from config into the subprocess adapter env", () => {
    // Verify that the factory correctly threads extraEnv through.
    // We can only inspect this indirectly — the adapter should construct without error
    // when extraEnv contains task-specific vars.
    withEnv({ EXECUTOR_PROFILE: "local-subprocess", EXECUTOR_TYPE: "claude" }, () => {
      const adapter = createExecutorAdapter({
        claudeExecutorDist: "/claude/dist",
        extraEnv: { TASK_BRANCH: "feature/foo", MAX_TURNS: "50" },
      });
      expect(adapter).toBeInstanceOf(SubProcessAdapter);
    });
  });

  it("hermes executor-type env takes lower precedence than caller extraEnv", () => {
    // The factory merges resolveExecutorEnv FIRST, then extraEnv on top.
    // Callers can override hermes defaults by setting the same key in extraEnv.
    // This is a design invariant — test it structurally via the factory call succeeding.
    withEnv({ EXECUTOR_PROFILE: "local-subprocess", EXECUTOR_TYPE: "hermes" }, () => {
      const adapter = createExecutorAdapter({
        hermesExecutorDist: "/hermes/dist",
        hermesModel: "base-model",
        hermesProvider: "deepseek",
        deepseekApiKey: "sk-test",
        // Caller overrides the model via extraEnv
        extraEnv: { HERMES_INFERENCE_MODEL: "override-model" },
      });
      expect(adapter).toBeInstanceOf(SubProcessAdapter);
    });
  });
});

// ── 4. Env var defaults ────────────────────────────────────────────────────────

describe("EXECUTOR_PROFILE and EXECUTOR_TYPE defaults", () => {
  it("EXECUTOR_PROFILE defaults to local-subprocess when unset", () => {
    withEnv({ EXECUTOR_PROFILE: undefined }, () => {
      // Should not throw — local-subprocess is the default
      expect(() => createExecutorAdapter({ claudeExecutorDist: "/claude/dist" })).not.toThrow();
    });
  });

  it("EXECUTOR_TYPE defaults to claude when unset", () => {
    withEnv({ EXECUTOR_TYPE: undefined }, () => {
      const adapter = createExecutorAdapter({ claudeExecutorDist: "/explicit/claude" });
      expect(adapter).toBeInstanceOf(SubProcessAdapter);
    });
  });
});

