/**
 * Smoke test: Claude executor entrypoint (runtime/executors/claude/src/index.ts).
 *
 * Drives the compiled executor binary (dist/index.js) directly with a stub
 * `claude` binary on PATH. Does NOT invoke a real LLM. The executor self-builds
 * its briefing from the cloned mgmt repo — no BRIEFING_PATH is required.
 *
 * The stub `claude` binary is a tiny Node.js script that writes a valid
 * result.json to RESULT_PATH and exits 0.
 *
 * Covers:
 *   1. Executor exits with code 0 on success (result.json written)
 *   2. result.json has the correct shape (terminal_status field)
 *   3. Executor exits 0 when claude writes a "blocked" result
 *   4. Executor exits 0 when impl repo has no toolchain markers
 *
 * Excluded from unit test suite (vitest.unit.config.ts).
 */

import { describe, it, expect, afterAll } from "vitest";
import {
  mkdirSync,
  mkdtempSync,
  writeFileSync,
  readFileSync,
  rmSync,
  existsSync,
  chmodSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { execSync, spawnSync } from "node:child_process";

const EXECUTOR_BIN = join(
  dirname(new URL(import.meta.url).pathname),
  "..",
  "..",
  "executors",
  "claude",
  "dist",
  "index.js",
);

const GIT_ENV = {
  GIT_AUTHOR_NAME: "Smoke Test",
  GIT_AUTHOR_EMAIL: "smoke@test.com",
  GIT_COMMITTER_NAME: "Smoke Test",
  GIT_COMMITTER_EMAIL: "smoke@test.com",
};

const tmpDirs: string[] = [];

function trackDir(d: string): string {
  tmpDirs.push(d);
  return d;
}

afterAll(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

/**
 * Create a minimal bare management repo with a stub task YAML.
 * Returns the file:// URL.
 */
function makeMinimalBareMgmtRepo(taskId: string, featureId: string): string {
  const bareDir = trackDir(mkdtempSync(join(tmpdir(), "smoke-mgmt-bare-")));
  execSync("git -c init.defaultBranch=main init --bare", {
    cwd: bareDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  const workDir = trackDir(mkdtempSync(join(tmpdir(), "smoke-mgmt-work-")));
  execSync(`git clone "${bareDir}" .`, {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git checkout -b main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  const tasksDir = join(workDir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${taskId}.yaml`),
    `id: ${taskId}\ntitle: Smoke test task\nrepo: smoke-repo\nstatus: in_progress\n`,
    "utf-8",
  );
  execSync("git add -A", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync('git commit -m "initial"', {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git push origin main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  return `file://${bareDir}`;
}

/**
 * Create a minimal bare git repo with one empty commit (no toolchain markers).
 * Returns the file:// URL.
 */
function makeMinimalBareRepo(prefix = "smoke-bare-", fileName = "README.md", fileContent = "# Smoke test repo\n"): { url: string; branch: string } {
  const bareDir = trackDir(mkdtempSync(join(tmpdir(), prefix)));
  execSync("git -c init.defaultBranch=main init --bare", {
    cwd: bareDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  const workDir = trackDir(mkdtempSync(join(tmpdir(), `${prefix}work-`)));
  execSync(`git clone "${bareDir}" .`, {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git checkout -b main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  writeFileSync(join(workDir, fileName), fileContent, "utf-8");
  execSync(`git add "${fileName}"`, {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync('git commit -m "initial"', {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git push origin main", {
    cwd: workDir,
