    const { url, branch } = makeMinimalBareRepo();
    repoUrl = url;
    repoBranch = branch;
  }

  const mgmtRepoUrl = makeMinimalBareMgmtRepo("T1", "smoke-feature");

  const stubDir = makeClaudeStub(terminalStatus);

