 * - POST requests (creating PR): returns a PR object.
 *
 * In practice, the executor always calls list first. If we return a pre-existing PR URL,
 * the list call causes openImplPR to short-circuit and return it.
 *
 * Returns the directory containing the stub (add to PATH).
 */
function makeCurlStub(prUrl = "https://github.com/stub-org/stub-repo/pull/1"): string {
  const stubDir = trackDir(mkdtempSync(join(tmpdir(), "curl-stub-")));
  // A counter file tracks calls so the first call (list) returns the existing PR.
  const counterFile = join(stubDir, ".call-count");
  const scriptContent = [
    "#!/usr/bin/env node",
    `const fs = require("node:fs");`,
    `const counterFile = ${JSON.stringify(counterFile)};`,
    `const prUrl = ${JSON.stringify(prUrl)};`,
    ``,
    `let count = 0;`,
    `try { count = parseInt(fs.readFileSync(counterFile, "utf-8").trim(), 10) || 0; } catch {}`,
    `fs.writeFileSync(counterFile, String(count + 1), "utf-8");`,
