    `// Check if this is a PR list request (has ?head= in the args)`,
    `const args = process.argv.slice(2).join(" ");`,
    `if (args.includes("?head=")) {`,
    `  // Return existing PR so openImplPR short-circuits.`,
    `  console.log(JSON.stringify([{ html_url: prUrl, number: 1 }]));`,
    `} else if (args.includes("-X") && args.includes("POST")) {`,
    `  console.log(JSON.stringify({ html_url: prUrl, number: 1 }));`,
    `} else {`,
    `  // Default: return empty for any other curl call (e.g., repo meta).`,
    `  console.log(JSON.stringify({ default_branch: "main" }));`,
    `}`,
    `process.exit(0);`,
  ].join("\n");

