// ── Executor runner ───────────────────────────────────────────────────────────

interface HermesSmokeOpts {
  hermesStubMode: "normal" | "sigkill";
  mgmtRepoUrl: string;
  implRepoUrl: string;
  implRepoBranch: string;
  taskId?: string;
  featureId?: string;
  /** Inject a pre-seeded curl stub for happy-path PR creation. */
  withCurlStub?: boolean;
  prUrl?: string;
}

function runHermesExecutor(opts: HermesSmokeOpts): {
  exitCode: number | null;
  result: Record<string, unknown> | null;
  executorWorkdir: string;
} {
  const {
    hermesStubMode,
    mgmtRepoUrl,
    implRepoUrl,
    implRepoBranch,
    taskId = "T1",
    featureId = "hermes-test-feature",
    withCurlStub = false,
    prUrl = "https://github.com/stub-org/stub-repo/pull/1",
  } = opts;

  const resultDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-result-")));
  const resultPath = join(resultDir, "result.json");
  const executorWorkdir = trackDir(mkdtempSync(join(tmpdir(), "hermes-workdir-")));

  const hermesStubDir = makeHermesStub(hermesStubMode);
  const curlStubDir = withCurlStub ? makeCurlStub(prUrl) : undefined;

  const pathPrefix = [
    hermesStubDir,
    ...(curlStubDir ? [curlStubDir] : []),
    process.env.PATH ?? "/usr/bin:/bin",
  ].join(":");

  const taskBranch = `feature/${featureId}-${taskId}`;

  const env: NodeJS.ProcessEnv = {
    ...process.env,
    PATH: pathPrefix,
    TASK_ID: taskId,
    FEATURE_ID: featureId,
    WORKSPACE_ID: "hermes-integration-test",
    TASK_REPO_URL: implRepoUrl,
    TASK_REPO_BRANCH: taskBranch,
    TASK_BASE_BRANCH: "main",
    EXECUTOR_WORKDIR: executorWorkdir,
    MGMT_REPO_URL: mgmtRepoUrl,
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: withCurlStub ? "stub-token" : "",
    HERMES_INFERENCE_MODEL: "stub-model",
    HERMES_INFERENCE_PROVIDER: "stub-provider",
    HERMES_MAX_TURNS: "10",
    GIT_AUTHOR_NAME: "Integration Test",
    GIT_AUTHOR_EMAIL: "test@example.com",
    GIT_COMMITTER_NAME: "Integration Test",
    GIT_COMMITTER_EMAIL: "test@example.com",
    CLAUDE_AGENT_RUNTIME: "1",
  };

  const proc = spawnSync("node", [HERMES_EXECUTOR_BIN], {
    env,
    encoding: "utf-8",
    timeout: 90_000,
  });

  let result: Record<string, unknown> | null = null;
  if (existsSync(resultPath)) {
    try {
      result = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
    } catch { /* ignore parse errors */ }
  }

  return { exitCode: proc.status, result, executorWorkdir };
}

// ── Tests ─────────────────────────────────────────────────────────────────────

/**
 * Happy path: normal hermes exit + stub curl returns a PR → result.json has in_review.
 */
describe("Hermes executor — happy path (normal exit)", () => {
  it("writes result.json with terminal_status: in_review after successful hermes run", () => {
    const mgmtRepoUrl = makeMinimalBareMgmtRepo("T1", "hermes-test-feature");
    const { url: implRepoUrl, branch: implRepoBranch } = makeMinimalBareImplRepo();

    const { exitCode, result } = runHermesExecutor({
      hermesStubMode: "normal",
      mgmtRepoUrl,
      implRepoUrl,
      implRepoBranch,
      withCurlStub: true,
    });

    expect(exitCode).toBe(0);
    expect(result).not.toBeNull();
    expect(result?.terminal_status).toBe("in_review");
    expect(typeof result?.pr_url).toBe("string");
  }, 90_000);
});

/**
 * Abnormal exit: hermes self-kills via SIGKILL → recovery produces blocked result.json.
 */
describe("Hermes executor — abnormal exit (SIGKILL recovery)", () => {
  it("produces a blocked result.json when hermes is killed with SIGKILL", () => {
    const mgmtRepoUrl = makeMinimalBareMgmtRepo("T2", "hermes-test-feature");
    const { url: implRepoUrl, branch: implRepoBranch } = makeMinimalBareImplRepo();

    const { exitCode, result } = runHermesExecutor({
      hermesStubMode: "sigkill",
      mgmtRepoUrl,
      implRepoUrl,
      implRepoBranch,
      taskId: "T2",
      // No curl stub — recovery falls back to no PR (empty GITHUB_TOKEN).
    });

    expect(exitCode).toBe(0);
    expect(result).not.toBeNull();
    expect(result?.terminal_status).toBe("blocked");
    // The terminal reason should indicate SIGKILL or a crash.
    const reason = String(result?.blocked_reason ?? "");
    expect(
      reason === "executor_signal_SIGKILL" ||
        reason === "executor_crashed" ||
        reason === "result_not_written",
    ).toBe(true);
  }, 90_000);
});

/**
 * Parallel isolation: two executor instances each use their own EXECUTOR_WORKDIR.
 * Neither HERMES_HOME nor git working dirs should conflict.
 */
describe("Hermes executor — parallel task isolation", () => {
  it("two concurrent executor instances complete without HERMES_HOME or git conflicts", async () => {
    const mgmtRepoUrl1 = makeMinimalBareMgmtRepo("T3", "hermes-feat-parallel-a");
    const { url: implRepoUrl1 } = makeMinimalBareImplRepo();

    const mgmtRepoUrl2 = makeMinimalBareMgmtRepo("T4", "hermes-feat-parallel-b");
    const { url: implRepoUrl2 } = makeMinimalBareImplRepo();

    // Run both executors in parallel via Promise.all (each in its own process).
    const runInstance = (n: number) =>
      new Promise<{ exitCode: number | null; result: Record<string, unknown> | null }>((resolve) => {
        const mgmtUrl = n === 1 ? mgmtRepoUrl1 : mgmtRepoUrl2;
        const implUrl = n === 1 ? implRepoUrl1 : implRepoUrl2;
        const taskId = n === 1 ? "T3" : "T4";
        const featureId = n === 1 ? "hermes-feat-parallel-a" : "hermes-feat-parallel-b";
        const { exitCode, result } = runHermesExecutor({
          hermesStubMode: "normal",
          mgmtRepoUrl: mgmtUrl,
          implRepoUrl: implUrl,
          implRepoBranch: "main",
          taskId,
          featureId,
          withCurlStub: true,
        });
        resolve({ exitCode, result });
      });

    const [inst1, inst2] = await Promise.all([runInstance(1), runInstance(2)]);

    // Both instances should exit cleanly (code 0).
    expect(inst1.exitCode).toBe(0);
    expect(inst2.exitCode).toBe(0);

    // Both should produce a valid result.json (in_review from happy path).
    expect(inst1.result?.terminal_status).toBe("in_review");
    expect(inst2.result?.terminal_status).toBe("in_review");
  }, 180_000);
});

