/**
 * Integration tests: Hermes executor entrypoint (runtime/executors/hermes/src/index.ts).
 *
 * Drives the compiled executor binary (dist/index.js) directly with:
 *   - A stub `hermes` binary on PATH that simulates normal or abnormal hermes behaviour.
 *   - Local bare git repos (file://) for both mgmt and impl.
 *
 * Covers:
 *   1. Happy path: normal hermes exit; executor phases 1–6 run; result.json has in_review.
 *      Recovery short-circuits because the stub pre-writes a valid in_review result.
 *   2. Abnormal exit (SIGKILL): recovery produces blocked/executor_signal_SIGKILL.
 *   3. Parallel isolation: two executor instances each use their own EXECUTOR_WORKDIR
 *      (and thus own HERMES_HOME) — both complete without conflicts.
 */

import { describe, it, expect, afterAll, beforeAll } from "vitest";
import {
  mkdirSync,
  mkdtempSync,
  writeFileSync,
  readFileSync,
  rmSync,
  existsSync,
  chmodSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { execSync, spawnSync, spawn } from "node:child_process";

// ── Constants ──────────────────────────────────────────────────────────────────

const HERMES_EXECUTOR_BIN = join(
  dirname(new URL(import.meta.url).pathname),
  "..",
  "..",
  "executors",
  "hermes",
  "dist",
  "index.js",
);

const GIT_ENV = {
  GIT_AUTHOR_NAME: "Integration Test",
  GIT_AUTHOR_EMAIL: "test@example.com",
  GIT_COMMITTER_NAME: "Integration Test",
  GIT_COMMITTER_EMAIL: "test@example.com",
};

// ── Cleanup tracking ──────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function trackDir(d: string): string {
  tmpDirs.push(d);
  return d;
}

afterAll(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

// ── Build hermes executor once ────────────────────────────────────────────────

beforeAll(() => {
  if (!existsSync(HERMES_EXECUTOR_BIN)) {
    const hermesDir = join(
      dirname(new URL(import.meta.url).pathname),
      "..",
      "..",
      "executors",
      "hermes",
    );
    execSync("npm run build", {
      cwd: hermesDir,
      stdio: "pipe",
      encoding: "utf-8",
    });
  }
}, 60_000);

// ── Repo builders ─────────────────────────────────────────────────────────────

function makeMinimalBareMgmtRepo(taskId: string, featureId: string): string {
  const bareDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-mgmt-bare-")));
  execSync("git -c init.defaultBranch=main init --bare", {
    cwd: bareDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  const workDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-mgmt-work-")));
  execSync(`git clone "${bareDir}" .`, {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git checkout -b main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  const tasksDir = join(workDir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(
    join(tasksDir, `${taskId}.yaml`),
    `id: ${taskId}\ntitle: Hermes integration test task\nrepo: impl\nstatus: in_progress\n`,
    "utf-8",
  );
  writeFileSync(
    join(workDir, "docs", "features", featureId, "tasks.md"),
    [`## ${taskId} — Hermes integration test task`, "", "### Description", "Test task."].join("\n"),
    "utf-8",
  );
  writeFileSync(
    join(workDir, "docs", "features", featureId, "technical-design.md"),
    "# Technical Design\n\nHermes integration test.",
    "utf-8",
  );

  execSync("git add -A", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync('git commit -m "initial"', {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git push origin main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  return `file://${bareDir}`;
}

function makeMinimalBareImplRepo(): string {
  const bareDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-impl-bare-")));
  execSync("git -c init.defaultBranch=main init --bare", {
    cwd: bareDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  const workDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-impl-work-")));
  execSync(`git clone "${bareDir}" .`, {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git checkout -b main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  writeFileSync(join(workDir, "README.md"), "# Hermes impl repo\n", "utf-8");
  execSync("git add README.md", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync('git commit -m "initial"', {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git push origin main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  return `file://${bareDir}`;
}

// ── Stub builders ─────────────────────────────────────────────────────────────

/**
 * Create a stub `hermes` binary.
 *
 * "normal" mode:
 *   - Writes a file to cwd (TASK_REPO_PATH) so Phase 6 has changes to commit.
 *   - Pre-writes a valid in_review result.json to RESULT_PATH so Layer 1 recovery
 *     short-circuits after Phase 6's openImplPR fails (file:// URL can't be parsed
 *     as GitHub coords). This verifies the recovery short-circuit path.
 *
 * "sigkill" mode:
 *   - Writes a file first (so Phase 6 commits something), then self-kills via SIGKILL.
 *   - No result.json is written, so recovery detects the abnormal exit.
 *
 * Returns the directory containing the stub (add to PATH).
 */
function makeHermesStub(mode: "normal" | "sigkill", prUrl?: string): string {
  const stubDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-stub-")));

  const scriptContent =
    mode === "sigkill"
      ? [
          "#!/usr/bin/env node",
          `const fs = require("node:fs");`,
          // Write a file so Phase 6 has changes to commit.
          `fs.writeFileSync("sigkill-output.txt", "written before kill\\n", "utf-8");`,
          // Self-kill with SIGKILL to simulate abnormal termination.
          `process.kill(process.pid, "SIGKILL");`,
        ].join("\n")
      : [
          "#!/usr/bin/env node",
          `const fs = require("node:fs");`,
          `const path = require("node:path");`,
          // Write a file so Phase 6 has changes to commit and push.
          `fs.writeFileSync("hermes-output.txt", "hermes was here\\n", "utf-8");`,
          // Pre-write a valid in_review result.json so recovery short-circuits
          // after Phase 6's openImplPR fails for the file:// URL.
          `const resultPath = process.env.RESULT_PATH;`,
          `if (resultPath) {`,
          `  fs.mkdirSync(path.dirname(resultPath), { recursive: true });`,
          `  fs.writeFileSync(resultPath, JSON.stringify({`,
          `    terminal_status: "in_review",`,
          `    pr_url: ${JSON.stringify(prUrl ?? "https://github.com/stub-org/stub-repo/pull/1")}`,
          `  }), "utf-8");`,
          `}`,
          `process.exit(0);`,
        ].join("\n");

  const stubPath = join(stubDir, "hermes");
  writeFileSync(stubPath, scriptContent, "utf-8");
  chmodSync(stubPath, 0o755);
  return stubDir;
}

// ── Synchronous executor runner ───────────────────────────────────────────────

interface HermesRunOpts {
  hermesStubMode: "normal" | "sigkill";
  mgmtRepoUrl: string;
  implRepoUrl: string;
  taskId?: string;
  featureId?: string;
  prUrl?: string;
}

function buildEnv(opts: HermesRunOpts & { resultPath: string; executorWorkdir: string; hermesStubDir: string }): NodeJS.ProcessEnv {
  const {
    mgmtRepoUrl,
    implRepoUrl,
    taskId = "T1",
    featureId = "hermes-test-feature",
    resultPath,
    executorWorkdir,
    hermesStubDir,
  } = opts;

  const taskBranch = `feature/${featureId}-${taskId}`;

  return {
    ...process.env,
    PATH: `${hermesStubDir}:${process.env.PATH ?? "/usr/bin:/bin"}`,
    TASK_ID: taskId,
    FEATURE_ID: featureId,
    WORKSPACE_ID: "hermes-integration-test",
    TASK_REPO_URL: implRepoUrl,
    TASK_REPO_BRANCH: taskBranch,
    TASK_BASE_BRANCH: "main",
    EXECUTOR_WORKDIR: executorWorkdir,
    MGMT_REPO_URL: mgmtRepoUrl,
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: "",
    HERMES_INFERENCE_MODEL: "stub-model",
    HERMES_INFERENCE_PROVIDER: "stub-provider",
    HERMES_MAX_TURNS: "10",
    GIT_AUTHOR_NAME: "Integration Test",
    GIT_AUTHOR_EMAIL: "test@example.com",
    GIT_COMMITTER_NAME: "Integration Test",
    GIT_COMMITTER_EMAIL: "test@example.com",
    CLAUDE_AGENT_RUNTIME: "1",
  };
}

function runHermesSync(opts: HermesRunOpts): {
  exitCode: number | null;
  result: Record<string, unknown> | null;
  executorWorkdir: string;
} {
  const resultDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-result-")));
  const resultPath = join(resultDir, "result.json");
  const executorWorkdir = trackDir(mkdtempSync(join(tmpdir(), "hermes-workdir-")));
  const hermesStubDir = makeHermesStub(opts.hermesStubMode, opts.prUrl);

  const env = buildEnv({ ...opts, resultPath, executorWorkdir, hermesStubDir });

  const proc = spawnSync("node", [HERMES_EXECUTOR_BIN], {
    env,
    encoding: "utf-8",
    timeout: 90_000,
  });

  let result: Record<string, unknown> | null = null;
  if (existsSync(resultPath)) {
    try {
      result = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
    } catch { /* ignore */ }
  }

  return { exitCode: proc.status, result, executorWorkdir };
}

// ── Async executor runner (for parallel test) ─────────────────────────────────

function runHermesAsync(opts: HermesRunOpts): Promise<{
  exitCode: number | null;
  result: Record<string, unknown> | null;
}> {
  return new Promise((resolve) => {
    const resultDir = trackDir(mkdtempSync(join(tmpdir(), "hermes-result-")));
    const resultPath = join(resultDir, "result.json");
    const executorWorkdir = trackDir(mkdtempSync(join(tmpdir(), "hermes-workdir-")));
    const hermesStubDir = makeHermesStub(opts.hermesStubMode, opts.prUrl);

    const env = buildEnv({ ...opts, resultPath, executorWorkdir, hermesStubDir });

    const child = spawn("node", [HERMES_EXECUTOR_BIN], { env, stdio: "pipe" });

    child.on("close", (code) => {
      let result: Record<string, unknown> | null = null;
      if (existsSync(resultPath)) {
        try {
          result = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
        } catch { /* ignore */ }
      }
      resolve({ exitCode: code, result });
    });

    child.on("error", () => {
      resolve({ exitCode: null, result: null });
    });
